function topFrequencySums(nums: number[], k: number, x: number): number[] {
  const out: number[] = [];
  for (let i = 0; i + k <= nums.length; i++) {
    const count = new Map<number, number>();
    for (let j = i; j < i + k; j++) count.set(nums[j], (count.get(nums[j]) ?? 0) + 1);
    const ranked = [...count].sort((a, b) => b[1] - a[1] || b[0] - a[0]);
    let sum = 0;
    for (const [v, c] of ranked.slice(0, x)) sum += v * c;
    out.push(sum);
  }
  return out;
}

