function topFrequencySums(nums: number[], k: number, x: number): number[] {
  const count = new Map<number, number>();
  const add = (v: number, d: number) => {
    const c = (count.get(v) ?? 0) + d;
    if (c === 0) count.delete(v); else count.set(v, c);
  };
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    add(nums[i], 1);
    if (i >= k) add(nums[i - k], -1);
    if (i < k - 1) continue;
    const ranked = [...count].sort((a, b) => b[1] - a[1] || b[0] - a[0]);
    let sum = 0;
    for (let t = 0; t < Math.min(x, ranked.length); t++) sum += ranked[t][0] * ranked[t][1];
    out.push(sum);
  }
  return out;
}

